mapper.sql:
h.quotation_id, h.quotation_no, TO_CHAR(h.business_date, 'YYYY-MM-DD') as business_date, h.business_date as sort_business_date, h.partner_id, p.partner_code, h.partner_name, h.warehouse_id, w.warehouse_code, h.warehouse_name, h.assignee_id, a.assignee_code, h.assignee_name, h.note, h.progress_status, h.deleted_yn, TO_CHAR(h.updated_at, 'YYYY-MM-DD HH24:MI:SS') as updated_at,
( select MIN(l.item_name) keep (DENSE_RANK first order by l.quotation_line_id) || case when count(*) > 1 then ' 외 ' || TO_CHAR(count(*) - 1) || '건' else '' end from quotation_line l where l.quotation_id = h.quotation_id and l.deleted_yn = 'N' ) as item_summary, ( select NVL(sum(l.total_amount),0) from quotation_line l where l.quotation_id = h.quotation_id and l.deleted_yn = 'N'
) as total_amount

where h.deleted_yn = 'N'
and h.progress_status = #{progressStatus}
and ( h.quotation_no LIKE '%' || UPPER(#{keyword}) || '%' or TO_CHAR(h.business_date, 'YYYY/MM/DD') LIKE '%' || UPPER(#{keyword}) || '%' or UPPER(h.partner_name) LIKE '%' || UPPER(#{keyword}) || '%' or UPPER(h.assignee_name) LIKE '%' || UPPER(#{keyword}) || '%' or UPPER(h.warehouse_name) LIKE '%' || UPPER(#{keyword}) || '%' or UPPER(h.note) LIKE '%' || UPPER(#{keyword}) || '%' or EXISTS( select 1 from QUOTATION_LINE search_line left join ITEM search_item on search_item.item_id = search_line.item_id where search_line.quotation_id = h.quotation_id and search_line.deleted_yn = 'N' and ( search_item.item_code LIKE '%' || UPPER(#{keyword}) || '%' or UPPER(search_line.item_name) LIKE '%' || UPPER(#{keyword}) || '%' ) ) )
